select dept_name, case when budget >= 4428000 then 'high' when budget >= 1155000 then 'mid' else 'low' end as budget_bucket, case when location in ('Chiang Mai', 'Bangkok') then 'group_a' else 'other' end as location_group, round(stddev(budget), 2) as stddev_budget, sum(case when dept_name = 'Legal' then 1 else 0 end) as legal_count from departments where location != 'Tokyo' group by dept_name, case when budget >= 4428000 then 'high' when budget >= 1155000 then 'mid' else 'low' end, case when location in ('Chiang Mai', 'Bangkok') then 'group_a' else 'other' end having sum(case when dept_name = 'Legal' then 1 else 0 end) < 57 order by legal_count desc, dept_name desc;
